// Narrow native helper/input-tail contract, generated by executing Cube.exe locally.
// GUI, resource costs, movement input and world effects are outside this adapter.
using System;
using System.Collections.Generic;
using UnityEngine;

namespace CubeGame.AlphaTransfer
{
    [Serializable] public class AlphaNativeRule
    {
        public int action,primaryAtMs,primaryNext,primaryLateNext,selectChangeMs,idleAtMs,strikeEndMs;
        public bool interruptReadyAtZero;
    }
    [Serializable] public class AlphaNativeProfile
    {
        public string id,evidence,scope;
        public int classId,weaponSubtype,offset70;
        public AlphaNativeRule[] rules;
        public AlphaNativeRule Rule(int action)=>Array.Find(rules,r=>r.action==action);
    }
    [Serializable] public class AlphaNativeCase
    {
        public string profile;
        public int action,timerMs,expectedAction,expectedTimerMs;
        public bool primary,secondary,blocked,expectedSelected;
    }
    [Serializable] public class AlphaNativeSpec
    {
        public string format,rig,status,source;
        public AlphaNativeProfile[] profiles;
        public AlphaNativeCase[] golden;
        public static AlphaNativeSpec Parse(string json,string rig)
        {
            var s=JsonUtility.FromJson<AlphaNativeSpec>(json);
            if(s==null||s.format!="cubegame.native_lifecycle/1"||s.rig!=rig||s.status!="EMULATED_ALPHA_CODE"
                ||s.profiles==null||s.profiles.Length==0||s.golden==null||s.golden.Length==0)
                throw new ArgumentException("NATIVE_SPEC_INVALID");
            var ids=new HashSet<string>();
            foreach(var p in s.profiles)
            {
                if(!ids.Add(p.id)||p.evidence!="VERIFIED_ALPHA"||p.offset70!=0||p.weaponSubtype!=15
                    ||p.rules==null||p.rules.Length==0)throw new ArgumentException("NATIVE_PROFILE_INVALID");
                var actions=new HashSet<int>();
                foreach(var r in p.rules)
                    if(!actions.Add(r.action)||r.primaryAtMs<0||r.strikeEndMs<0||r.idleAtMs< -1
                        ||r.selectChangeMs< -1||r.primaryNext<0||r.primaryLateNext<0)
                        throw new ArgumentException("NATIVE_RULE_INVALID");
                foreach(var r in p.rules)if(p.Rule(r.primaryNext)==null||p.Rule(r.primaryLateNext)==null)
                    throw new ArgumentException("NATIVE_RULE_TARGET_MISSING");
            }
            return s;
        }
        public AlphaNativeProfile Profile(string id)=>Array.Find(profiles,p=>p.id==id)
            ??throw new ArgumentException("NATIVE_CONTEXT_UNSUPPORTED "+id);
    }
    public struct AlphaNativeOutcome {public int action,timerMs;public bool selected;}
    public static class AlphaNativeInput
    {
        public static AlphaNativeOutcome Decide(AlphaNativeProfile p,int action,int timer,bool primary,bool secondary,bool blocked)
        {
            if(timer<0)throw new ArgumentException("NATIVE_TIMER_INVALID");
            var r=p.Rule(action)??throw new ArgumentException("NATIVE_ACTION_UNSUPPORTED "+action);
            var o=new AlphaNativeOutcome{action=action,timerMs=timer};
            if(primary&&!blocked&&timer>=r.primaryAtMs)
            {
                o.selected=true;o.timerMs=0;
                o.action=r.selectChangeMs>=0&&timer>=r.selectChangeMs?r.primaryLateNext:r.primaryNext;
            }
            r=p.Rule(o.action);
            if(!secondary&&r.idleAtMs>=0&&o.timerMs>=r.idleAtMs)o.action=0; // native timer is NOT reset
            return o;
        }
    }

}
